# All 9 planets x 27 nakshatras = 243 entries complete


# =================================================================
# ANALYSIS FUNCTIONS
# =================================================================

from app.nakshatra import NAKSHATRAS


def _find_nakshatra(longitude: float) -> dict:
    """Find which nakshatra a given sidereal longitude falls in."""
    lon = longitude % 360.0
    for nak in NAKSHATRAS:
        if nak["start"] <= lon < nak["end"]:
            return nak
    return NAKSHATRAS[0]


def _find_pada(longitude: float, nak_start: float) -> int:
    """Determine pada (1-4) within a nakshatra. Each pada = 3°20'."""
    offset = (longitude % 360.0) - nak_start
    if offset < 0:
        offset += 360.0
    pada = int(offset / 3.333333) + 1
    return min(max(pada, 1), 4)


def calculate_nakshatra_analysis(planets: list, ascendant: dict) -> dict:
    """
    Complete Nakshatra-based prediction for all planets.
    Returns detailed personality, events, career, relationship,
    health, financial, spiritual analysis per planet-nakshatra combo,
    plus multi-planet and nakshatra-lord chain analysis.
    """

    asc_sign = ascendant.get("sign", "Aries")
    results = []
    nak_groups = {}  # group planets by nakshatra for multi-planet analysis

    for p in planets:
        pname = p.get("planet", "")
        lon = p.get("longitude", 0.0)

        nak = _find_nakshatra(lon)
        nak_name = nak["name"]
        nak_lord = nak["lord"]
        pada = _find_pada(lon, nak["start"])

        # Get nakshatra details
        nak_detail = NAKSHATRA_DETAILS.get(nak_name, {})

        # Get planet-in-nakshatra prediction
        planet_nak = PLANET_IN_NAKSHATRA.get(pname, {}).get(nak_name, {})

        # Get pada info
        pada_info = NAKSHATRA_PADAS.get(nak_name, {}).get(pada, {})

        # Track for multi-planet analysis
        if nak_name not in nak_groups:
            nak_groups[nak_name] = []
        nak_groups[nak_name].append(pname)

        results.append({
            "planet": pname,
            "longitude": round(lon, 4),
            "nakshatra": nak_name,
            "nakshatra_lord": nak_lord,
            "pada": pada,
            "pada_navamsha": pada_info.get("navamsha_sign", ""),
            "pada_quality": pada_info.get("quality", ""),
            # Nakshatra attributes
            "deity": nak_detail.get("deity", ""),
            "symbol": nak_detail.get("symbol", ""),
            "shakti": nak_detail.get("shakti", ""),
            "guna": nak_detail.get("guna", ""),
            "gana": nak_detail.get("gana", ""),
            "animal": nak_detail.get("animal", ""),
            "element": nak_detail.get("element", ""),
            "body_part": nak_detail.get("body_part", ""),
            "dosha": nak_detail.get("dosha", ""),
            "motivation": nak_detail.get("motivation", ""),
            "temperament": nak_detail.get("temperament", ""),
            # General nakshatra traits
            "general_traits": nak_detail.get("general_traits", ""),
            "career_traits": nak_detail.get("career_traits", ""),
            "relationship_traits": nak_detail.get("relationship_traits", ""),
            "health_traits": nak_detail.get("health_traits", ""),
            "financial_traits": nak_detail.get("financial_traits", ""),
            "spiritual_traits": nak_detail.get("spiritual_traits", ""),
            "negative_traits": nak_detail.get("negative_traits", ""),
            # Planet-specific nakshatra predictions
            "personality": planet_nak.get("personality", ""),
            "nature": planet_nak.get("nature", ""),
            "events": planet_nak.get("events", ""),
            "career": planet_nak.get("career", ""),
            "relationship": planet_nak.get("relationship", ""),
            "health": planet_nak.get("health", ""),
            "financial": planet_nak.get("financial", ""),
            "spiritual": planet_nak.get("spiritual", ""),
            "age_events": planet_nak.get("age_events", []),
            "remedies": planet_nak.get("remedies", ""),
        })

    # Multi-planet nakshatra analysis
    multi_planet = []
    for nak_name, planet_list in nak_groups.items():
        if len(planet_list) >= 2:
            nak_detail = NAKSHATRA_DETAILS.get(nak_name, {})
            combined_desc = (
                f"{', '.join(planet_list)} are all in {nak_name} nakshatra "
                f"(deity: {nak_detail.get('deity', '')}, lord: {_find_nakshatra_lord(nak_name)}). "
                f"This intensifies {nak_name}'s energy enormously. "
                f"The combined force of {len(planet_list)} planets in one nakshatra "
                f"creates a laser-focused life theme around {nak_detail.get('shakti', 'this shakti')}. "
            )
            # Describe specific planet interactions
            if "Sun" in planet_list and "Moon" in planet_list:
                combined_desc += "Sun-Moon conjunction here creates an Amavasya (new moon) energy — powerful but internally conflicted. Identity and emotions are fused. "
            if "Rahu" in planet_list and ("Sun" in planet_list or "Moon" in planet_list):
                combined_desc += "Grahan (eclipse) yoga in this nakshatra — sudden events, confusion, but also karmic breakthroughs. "
            if "Jupiter" in planet_list and "Rahu" in planet_list:
                combined_desc += "Guru Chandal yoga — wisdom mixed with unconventional/foreign influence. Can be brilliant or misguided. "
            if "Mars" in planet_list and "Saturn" in planet_list:
                combined_desc += "Angarak-Shani combination — intense frustration, delayed action, but immense endurance when channeled properly. "
            if "Venus" in planet_list and "Saturn" in planet_list:
                combined_desc += "Delayed love/luxury but extremely stable once achieved. Artistic mastery through discipline. "
            if "Mars" in planet_list and "Rahu" in planet_list:
                combined_desc += "Angarak yoga — explosive energy, accidents possible, but also extraordinary courage and tech-warrior abilities. "

            multi_planet.append({
                "nakshatra": nak_name,
                "planets": planet_list,
                "count": len(planet_list),
                "deity": nak_detail.get("deity", ""),
                "shakti": nak_detail.get("shakti", ""),
                "combined_effect": combined_desc,
                "intensity": "Extremely High" if len(planet_list) >= 3 else "Very High",
            })

    # Ascendant nakshatra
    asc_lon = ascendant.get("longitude", 0.0)
    asc_nak = _find_nakshatra(asc_lon)
    asc_nak_detail = NAKSHATRA_DETAILS.get(asc_nak["name"], {})
    asc_pada = _find_pada(asc_lon, asc_nak["start"])
    asc_pada_info = NAKSHATRA_PADAS.get(asc_nak["name"], {}).get(asc_pada, {})

    ascendant_analysis = {
        "nakshatra": asc_nak["name"],
        "lord": asc_nak["lord"],
        "pada": asc_pada,
        "pada_navamsha": asc_pada_info.get("navamsha_sign", ""),
        "deity": asc_nak_detail.get("deity", ""),
        "symbol": asc_nak_detail.get("symbol", ""),
        "temperament": asc_nak_detail.get("temperament", ""),
        "general_traits": asc_nak_detail.get("general_traits", ""),
        "career_traits": asc_nak_detail.get("career_traits", ""),
        "health_traits": asc_nak_detail.get("health_traits", ""),
        "spiritual_traits": asc_nak_detail.get("spiritual_traits", ""),
    }

    return {
        "type": "nakshatra_predictions",
        "ascendant_nakshatra": ascendant_analysis,
        "planet_nakshatras": results,
        "multi_planet_nakshatras": multi_planet,
    }


def _find_nakshatra_lord(nak_name: str) -> str:
    """Helper to get lord of a nakshatra by name."""
    for n in NAKSHATRAS:
        if n["name"] == nak_name:
            return n["lord"]
    return ""

